"""Reproduce the isolated source-measured navmesh height candidate; never adopt it."""
import os,sys,json,subprocess,hashlib,argparse,re
from pathlib import Path
assert os.environ.get('CASE1_PROTECTION')
P=argparse.ArgumentParser();P.add_argument('--run',required=True);args=P.parse_args();assert re.fullmatch('pRb-source-ground-plane-[A-Za-z0-9-]+',args.run)
R=Path.cwd();B=R/'outputs/landmark-connectivity';O=B/args.run;O.mkdir(exist_ok=False);build=R/'.cache/navmesh-plane-height-candidate';build.mkdir(exist_ok=True);cpp=R/'tests/landmark_diagnostics/navmesh_plane_height_candidate.cpp';exe=build/(args.run+'-builder');subprocess.run(['g++','-std=c++17','-O2','-Iupstream/habitat-sim/src/deps/recastnavigation/Detour/Include',str(cpp),'-o',str(exe)],check=True)
gap_path=B/'pRb-ground-height-gap-v1/validation.json';gap=json.loads(gap_path.read_text());assert not gap['hypothetical_point_contacts'] and not gap['exact_mesh_membership_pass'];m=json.loads((B/'full-native-v11/manifest.json').read_text());profile=json.loads(Path(m['profile_path']).read_text());source=Path(profile['assets']['mp3d/pRbA3pwrgk9/pRbA3pwrgk9.glb']['navmesh_path']);assert hashlib.sha256(source.read_bytes()).hexdigest()==gap['mesh_sha256'];dest=O/'candidate.navmesh';command=[str(exe),str(source),str(dest),str(gap['original_snap'][1]),str(gap['hypothetical_lifted_point'][1])];p=subprocess.run(command,text=True,capture_output=True);(O/'build.log').write_text(p.stdout+'\n'+p.stderr);assert p.returncode==0,p.returncode;r=json.loads(p.stdout);r.update(status='EXPERIMENTAL_PLANE_HEIGHT_CANDIDATE_NOT_ADOPTED',source_mesh_path=str(source),source_mesh_sha256=hashlib.sha256(source.read_bytes()).hexdigest(),candidate_mesh_sha256=hashlib.sha256(dest.read_bytes()).hexdigest(),source_geometry_evidence_sha256=hashlib.sha256(gap_path.read_bytes()).hexdigest(),builder_sha256=hashlib.sha256(cpp.read_bytes()).hexdigest(),driver_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),limits='Measured source-ground correction of one exact navmesh height layer only. No scene geometry, topology, body, BV bucket or other file-byte changes. Diagnostic, not adopted; all body/connectivity/motion checks still required.');(O/'build-receipt.json').write_text(json.dumps(r,indent=2));print(r['candidate_mesh_sha256'],r['changed_floats'])
